ys":null,"dueDays":null,"doneDaysAgo":null},{"type":"Task","title":"Eski VPN sunucusunu kapat","status":"todo","assignee":"ali@anka.com","points":3,"sprint":3,"parent":"ANK-3","priority":"Medium","labels":["altyapı"],"description":"","startDays":null,"dueDays":null,"doneDaysAgo":null},{"type":"Task","title":"Eski istemciyi tüm cihazlardan kaldır","status":"todo","assignee":"emre@anka.com","points":5,"sprint":3,"parent":"ANK-3","priority":"Medium","labels":[],"description":"","startDays":null,"dueDays":null,"doneDaysAgo":null},{"type":"Story","title":"Yöneticiler VPN kullanım raporunu görebilmeli","status":"todo","assignee":null,"points":5,"sprint":null,"parent":null,"priority":"Low","labels":[],"description":"","startDays":null,"dueDays":null,"doneDaysAgo":null},{"type":"Task","title":"VPN log saklama süresini KVKK'ya göre ayarla","status":"todo","assignee":null,"points":3,"sprint":null,"parent":null,"priority":"Medium","labels":["güvenlik"],"description":"","startDays":null,"dueDays":null,"doneDaysAgo":null}],"links":[["ANK-12","ANK-11","blocks"],["ANK-12","ANK-18","blocks"],["ANK-14","ANK-11","relates"]],"comments":[["ANK-12","ali@anka.com","Lisans anahtarı tedarikçiden henüz gelmedi, bekliyorum."],["ANK-11","ayse@anka.com","Yük dengeleyici hazır olmadan 3. ve 4. katlara kurulum yapamıyoruz."],["ANK-14","mehmet@anka.com","Düzeltme hazır, @Ali Çelik incelemesini bekliyor."]]},{"key":"ERP","name":"ERP Entegrasyonu","description":"Logo ERP ile destek platformunun entegrasyonu","manager":"yonetici@anka.com","members":["yonetici@anka.com","mehmet@anka.com","ayse@anka.com"],"sprints":[],"items":[{"type":"Epic","title":"Analiz ve tasarım","status":"done","assignee":"yonetici@anka.com","points":null,"sprint":null,"parent":null,"priority":"Medium","labels":[],"description":"","startDays":-30,"dueDays":-10,"doneDaysAgo":10},{"type":"Epic","title":"Masraf modülü entegrasyonu","status":"in_progress","assignee":"mehmet@anka.com","points":null,"sprint":null,"parent":null,"priority":"Medium","labels":[],"description":"","startDays":-8,"dueDays":14,"doneDaysAgo":null},{"type":"Epic","title":"Raporlama","status":"todo","assignee":"ayse@anka.com","points":null,"sprint":null,"parent":null,"priority":"Medium","labels":[],"description":"","startDays":12,"dueDays":35,"doneDaysAgo":null},{"type":"Task","title":"Mevcut süreçlerin analizi","status":"done","assignee":"ayse@anka.com","points":5,"sprint":null,"parent":"ERP-1","priority":"Medium","labels":[],"description":"","startDays":-30,"dueDays":-20,"doneDaysAgo":20},{"type":"Task","title":"Veri modeli tasarımı","status":"done","assignee":"mehmet@anka.com","points":8,"sprint":null,"parent":"ERP-1","priority":"Medium","labels":[],"description":"","startDays":-20,"dueDays":-10,"doneDaysAgo":11},{"type":"Story","title":"Çalışan masraf formunu platformdan gönderebilmeli","status":"in_progress","assignee":"mehmet@anka.com","points":8,"sprint":null,"parent":"ERP-2","priority":"High","labels":[],"description":"","startDays":-8,"dueDays":6,"doneDaysAgo":null},{"type":"Task","title":"Logo API bağlantısı","status":"in_review","assignee":"mehmet@anka.com","points":5,"sprint":null,"parent":"ERP-2","priority":"Medium","labels":[],"description":"","startDays":-8,"dueDays":0,"doneDaysAgo":null},{"type":"Task","title":"Onay akışı (yönetici → muhasebe)","status":"todo","assignee":"ayse@anka.com","points":5,"sprint":null,"parent":"ERP-2","priority":"Medium","labels":[],"description":"","startDays":2,"dueDays":14,"doneDaysAgo":null},{"type":"Task","title":"Aylık masraf raporu","status":"todo","assignee":null,"points":5,"sprint":null,"parent":"ERP-3","priority":"Medium","labels":[],"description":"","startDays":12,"dueDays":30,"doneDaysAgo":null}],"links":[["ERP-7","ERP-6","blocks"]],"comments":[]}],"articles":[{"title":"VPN bağlanmıyor","category":"Ağ/VPN","body":"VPN istemcisi (Anka Connect) bağlanmıyorsa sırayla şunları deneyin:\n1) İnternet bağlantınızın çalıştığını bir web sitesi açarak kontrol edin.\n2) Anka Connect'i sağ alttaki simgeden tamamen kapatıp yeniden açın.\n3) Sunucu adresinin vpn.anka.com.tr olduğundan emin olun.\n4) Kullanıcı adınızı 'anka\\kullaniciadi' biçiminde, şirket şifrenizle girin.\n5) Telefonunuzdaki Authenticator bildirimini 60 saniye içinde onaylayın.\n6) Hâlâ bağlanmıyorsa bilgisayarı yeniden başlatın ve 'Ağ/VPN' kategorisinde ticket açın; ekran görüntüsü ekleyin."},{"title":"VPN bağlantısı sık sık kopuyor","category":"Ağ/VPN","body":"Bağlantı birkaç dakikada bir kopuyorsa:\n1) Wi-Fi yerine mümkünse kablolu bağlantı kullanın.\n2) Anka Connect > Ayarlar > 'Bağlantı koptuğunda otomatik yeniden bağlan' seçeneğini açın.\n3) Güç ayarlarında 'Ağ bağdaştırıcısının gücünü kapatmasına izin ver' seçeneğini kaldırın (Aygıt Yöneticisi > Ağ bağdaştırıcıları > Özellikler > Güç Yönetimi).\n4) Anka Connect sürümünüz 5.2'den eskiyse Yazılım Merkezi'nden güncelleyin."},{"title":"VPN istemcisi kurulumu (Anka Connect)","category":"Ağ/VPN","body":"Yeni bilgisayara VPN kurmak için:\n1) Başlat menüsünden 'Yazılım Merkezi'ni açın.\n2) 'Anka Connect' uygulamasını bulun ve 'Yükle'ye tıklayın.\n3) Kurulum bitince bilgisayarı yeniden başlatın.\n4) Anka Connect'i açın, sunucu olarak vpn.anka.com.tr yazın ve şirket hesabınızla giriş yapın.\nKişisel bilgisayarlara VPN kurulmaz; sadece şirket cihazları desteklenir."},{"title":"Ofis Wi-Fi ağına bağlanma","category":"Ağ/VPN","body":"Şirket cihazları 'Anka-Kurumsal' ağına otomatik bağlanır. Bağlanmıyorsa:\n1) Wi-Fi listesinde 'Anka-Kurumsal' ağını seçip 'Unut' deyin.\n2) Tekrar seçin; kullanıcı adı olarak şirket e-postanızı, şifre olarak şirket şifrenizi girin.\n3) Sertifika uyarısı çıkarsa 'Bağlan'ı seçin.\nMisafirler ve kişisel telefonlar için 'Anka-Misafir' ağı kullanılır; şifresi resepsiyondadır ve her pazartesi değişir."},{"title":"İnternet çok yavaş","category":"Ağ/VPN","body":"İnternet yavaşsa:\n1) speedtest.anka.local adresinden hız testi yapın; 20 Mbps altındaysa not alın.\n2) VPN açıksa ve ofisteyseniz VPN'i kapatın; ofiste VPN gerekmez.\n3) Arka planda büyük dosya senkronizasyonu (OneDrive) olup olmadığını kontrol edin.\n4) Sorun tüm katta varsa 'Ağ/VPN' kategorisinde ticket açın ve kat bilgisini yazın."},{"title":"Paylaşımlı klasöre (dosya sunucusu) erişim","category":"Ağ/VPN","body":"Ortak klasörler \\\\dosya.anka.local adresindedir.\n1) Dosya Gezgini'nin adres çubuğuna \\\\dosya.anka.local yazın.\n2) Evden çalışıyorsanız önce VPN'e bağlanın.\n3) 'Erişim reddedildi' hatasında klasör sahibinin onayı gerekir; 'Erişim/Hesap' kategorisinde klasör adını yazarak ticket açın."},{"title":"Outlook e-postaları senkronize etmiyor","category":"E-posta","body":"Yeni e-postalar gelmiyorsa:\n1) Outlook'un sağ altında 'Bağlantı kesildi' yazıyor mu bakın; yazıyorsa internetinizi kontrol edin.\n2) Gönder/Al > Tüm Klasörleri Gönder/Al'a tıklayın.\n3) Outlook'u kapatın, Denetim Masası > Posta > Profiller > Profili onar adımını uygulayın.\n4) Posta kutunuz %95 doluysa eski e-postaları arşivleyin (bkz. 'Posta kutusu dolu' makalesi)."},{"title":"Posta kutusu dolu uyarısı","category":"E-posta","body":"Posta kutusu kotası 50 GB'dır. Dolduğunda e-posta gönderemezsiniz.\n1) Outlook > Dosya > Araçlar > Posta Kutusu Temizleme'yi açın.\n2) 'Silinmiş Öğeler'i boşaltın.\n3) 1 yıldan eski e-postaları Arşiv klasörüne taşıyın (Dosya > Araçlar > Eski Öğeleri Temizle).\n4) Büyük ekli e-postaları bulmak için arama kutusuna 'boyut:çok büyük' yazın.\nKota artırımı sadece yönetici onayıyla yapılır."},{"title":"Outlook sürekli şifre soruyor","category":"E-posta","body":"Outlook her açılışta şifre istiyorsa:\n1) Outlook'u kapatın.\n2) Başlat > 'Kimlik Bilgileri Yöneticisi' > Windows Kimlik Bilgileri'ni açın.\n3) 'MicrosoftOffice' ve 'outlook' ile başlayan kayıtları silin.\n4) Outlook'u açın, şirket e-postanız ve şifrenizle bir kez giriş yapın, 'Beni hatırla'yı işaretleyin.\nŞifrenizi yakın zamanda değiştirdiyseniz bu adım mutlaka gereklidir."},{"title":"E-posta imzası oluşturma","category":"E-posta","body":"Kurumsal imza şablonu zorunludur.\n1) Outlook > Dosya > Seçenekler > Posta > İmzalar'ı açın.\n2) 'Yeni'ye tıklayın, adını 'Anka' yapın.\n3) intranet.anka.local/imza adresindeki şablonu kopyalayıp yapıştırın, kendi adınızı, unvanınızı ve dahili numaranızı yazın.\n4) 'Yeni iletiler' ve 'Yanıtlar' için bu imzayı seçin."},{"title":"Spam ve oltalama (phishing) e-postaları","category":"E-posta","body":"Şüpheli bir e-posta aldıysanız:\n1) Bağlantılara tıklamayın, ekleri açmayın.\n2) Outlook'ta 'Oltalama Bildir' düğmesine basın; e-posta güvenlik ekibine iletilir.\n3) Yanlışlıkla tıkladıysanız hemen şifrenizi değiştirin ve 'Erişim/Hesap' kategorisinde 'Acil' öncelikli ticket açın.\nAnka IT ekibi sizden asla e-postayla şifre istemez."},{"title":"E-posta eki açılmıyor","category":"E-posta","body":"PDF veya Office ekleri açılmıyorsa:\n1) Eki önce masaüstüne kaydedin, sonra açın.\n2) PDF için Adobe Reader'ın yüklü olduğundan emin olun (Yazılım Merkezi).\n3) Güvenlik nedeniyle .exe, .bat ve .js uzantılı ekler otomatik engellenir; bu dosyaları paylaşımlı klasör üzerinden isteyin."},{"title":"Yazıcı çıktı vermiyor","category":"Donanım","body":"Yazıcıdan çıktı alamıyorsanız:\n1) Yazıcının açık olduğunu ve ekranında hata olmadığını kontrol edin.\n2) Bilgisayarda Ayarlar > Yazıcılar'dan katınızdaki yazıcıyı (ör. 'Kat2-Yazıcı') varsayılan yapın.\n3) Yazdırma kuyruğunu açıp takılı işleri iptal edin.\n4) Kuyruk temizlenmiyorsa bilgisayarı yeniden başlatın."},{"title":"Yazıcı kağıt sıkıştırıyor","category":"Donanım","body":"Kağıt sıkışmasında:\n1) Yazıcıyı kapatın, ön kapağı açın.\n2) Sıkışan kağıdı iki elinizle yavaşça, kağıt yolunun yönünde çekin; yırtmamaya dikkat edin.\n3) Kağıt tepsisindeki kağıtların düzgün ve 250 yaprağı geçmediğinden emin olun.\n4) Sık tekrarlıyorsa silindir temizliği gerekir; 'Donanım' kategorisinde ticket açın."},{"title":"Toner ve kartuş değişimi","category":"Donanım","body":"Toner bitti uyarısında:\n1) Yedek tonerler her katın malzeme dolabındadır (dolap anahtarı kat sorumlusunda).\n2) Ön kapağı açın, eski toneri çekip çıkarın, yenisini klik sesi gelene kadar itin.\n3) Dolapta toner yoksa 'Donanım' kategorisinde yazıcı adını yazarak ticket açın; 1 iş günü içinde getirilir."},{"title":"Laptop çok ısınıyor veya yavaşladı","category":"Donanım","body":"Bilgisayarınız ısınıyor ya da yavaşladıysa:\n1) Laptopu yumuşak yüzeylerde (yatak, kucak) değil, düz masada kullanın.\n2) Görev Yöneticisi'nde (Ctrl+Shift+Esc) çok işlemci kullanan uygulamaları kapatın.\n3) Bilgisayarı en az haftada bir yeniden başlatın; güncellemeler ancak böyle tamamlanır.\n4) Fan sesi çok yüksekse veya cihaz kendiliğinden kapanıyorsa 'Donanım' ticketı açın; bakım için cihaz alınır."},{"title":"Harici monitör algılanmıyor","category":"Donanım","body":"İkinci ekran görüntü vermiyorsa:\n1) Kablonun (HDMI/USB-C) iki ucunu da çıkarıp takın.\n2) Windows + P tuşlarına basıp 'Genişlet'i seçin.\n3) Docking istasyonu kullanıyorsanız docking'in güç kablosunu çıkarıp 10 saniye bekleyin.\n4) Başka kablo ile deneyin; masa kablosu arızalıysa 'Donanım' ticketı açın."},{"title":"Yeni ekipman talebi (mouse, klavye, kulaklık)","category":"Donanım","body":"Mouse, klavye, kulaklık gibi küçük ekipmanlar için:\n1) 'Donanım' kategorisinde ticket açın, başlığa ekipman adını yazın.\n2) Açıklamaya teslim alacağınız katı ve masa numaranızı ekleyin.\n3) Stoktaki ekipmanlar 2 iş günü içinde teslim edilir. Monitör ve laptop talepleri yönetici onayı gerektirir."},{"title":"Office lisans hatası","category":"Yazılım/Lisans","body":"Word/Excel 'Lisanssız ürün' diyorsa:\n1) Office uygulamasında Dosya > Hesap'a gidin.\n2) 'Oturumu kapat'a tıklayın, uygulamayı kapatıp açın.\n3) Şirket e-postanızla tekrar giriş yapın.\n4) Hâlâ lisanssız görünüyorsa hesabınıza lisans atanmamış olabilir; 'Yazılım/Lisans' ticketı açın."},{"title":"Yazılım kurulum talebi","category":"Yazılım/Lisans","body":"Bilgisayarınıza program kurma yetkiniz yoktur.\n1) Önce Başlat > 'Yazılım Merkezi'nde aradığınız programın olup olmadığına bakın; varsa kendiniz kurabilirsiniz.\n2) Yoksa 'Yazılım/Lisans' kategorisinde ticket açın; program adını, sürümünü ve iş gerekçesini yazın.\n3) Ücretli yazılımlar yönetici onayından sonra 3-5 iş günü içinde kurulur."},{"title":"Teams toplantısında ses veya kamera çalışmıyor","category":"Yazılım/Lisans","body":"Teams'te sizi duymuyorlarsa veya kamera açılmıyorsa:\n1) Teams > Ayarlar > Cihazlar'dan doğru mikrofon ve kamerayı seçin.\n2) Windows Ayarlar > Gizlilik > Kamera/Mikrofon'da Teams'e izin verildiğinden emin olun.\n3) Laptopunuzda kamera kapağı veya F8/F10 kamera kapatma tuşu olup olmadığını kontrol edin.\n4) Teams'i tamamen kapatıp (sağ alttaki simgeden 'Çık') yeniden açın."},{"title":"Windows güncellemesi takıldı","category":"Yazılım/Lisans","body":"Güncelleme %0'da veya uzun süre takılı kalıyorsa:\n1) Bilgisayarı prize takılı tutun ve 1 saat bekleyin.\n2) Değişmezse Ayarlar > Windows Update > 'Sorun gider'i çalıştırın.\n3) Güncellemeyi iptal etmek için bilgisayarı zorla kapatmayın; dosyalar bozulabilir.\n4) 3 saati geçerse 'Yazılım/Lisans' ticketı açın."},{"title":"ERP (Logo) uygulamasına giriş sorunu","category":"Yazılım/Lisans","body":"ERP'ye giremiyorsanız:\n1) ERP'ye sadece ofis ağından veya VPN üzerinden erişilebilir.\n2) Kullanıcı adınız sicil numaranızdır (ör. 10234), şifreniz şirket şifrenizden ayrıdır.\n3) Şifrenizi unuttuysanız ERP giriş ekranındaki 'Şifremi unuttum' bağlantısını kullanın.\n4) 'Yetkiniz yok' hatasında departman yöneticinizin onayıyla 'Erişim/Hesap' ticketı açın."},{"title":"Şirket şifremi unuttum, nasıl sıfırlarım?","category":"Erişim/Hesap","body":"Şirket (Windows/e-posta) şifrenizi unuttuysanız:\n1) portal.anka.local adresine gidin ve 'Şifremi unuttum'a tıklayın.\n2) Şirket e-postanızı yazın; telefonunuza gelen 6 haneli kodu girin.\n3) Yeni şifre belirleyin: en az 12 karakter, büyük-küçük harf ve rakam içermeli, son 5 şifrenizle aynı olmamalı.\n4) Telefonunuz kayıtlı değilse kimliğinizle IT ofisine (Kat 1) gelin."},{"title":"Hesabım kilitlendi","category":"Erişim/Hesap","body":"5 hatalı şifre denemesinden sonra hesabınız 30 dakika kilitlenir.\n1) 30 dakika bekleyin ve doğru şifreyle tekrar deneyin.\n2) Telefonunuzda eski şifreyle e-posta kuran uygulamalar sürekli deneme yapıp hesabı tekrar kilitleyebilir; telefondaki şifreyi güncelleyin.\n3) Acil durumda portal.anka.local üzerinden şifre sıfırlamak kilidi de kaldırır."},{"title":"İki adımlı doğrulama (Authenticator) kurulumu","category":"Erişim/Hesap","body":"Şirket hesapları için Microsoft Authenticator zorunludur.\n1) Telefonunuza 'Microsoft Authenticator' uygulamasını indirin.\n2) Bilgisayarda aka.ms/mfasetup adresine gidin ve 'Yöntem ekle' > 'Authenticator uygulaması'nı seçin.\n3) Ekrandaki QR kodu uygulamayla okutun.\nTelefon değiştirdiyseniz eski telefon elinizdeyse aynı adımları yeni telefonda yapın; değilse IT ofisine kimliğinizle başvurun."},{"title":"Yeni çalışan hesabı açma","category":"Erişim/Hesap","body":"Yeni başlayan çalışan için hesap talebi işe başlamadan en az 3 iş günü önce yapılmalıdır.\n1) İK, işe giriş formunu doldurduğunda talep otomatik oluşur.\n2) Yönetici, 'Erişim/Hesap' kategorisinde ticket açarak gerekli klasör ve uygulama yetkilerini (ERP modülleri, ortak klasörler) yazar.\n3) Hesap bilgileri ilk gün IT ofisinde (Kat 1) çalışana teslim edilir."},{"title":"İşten ayrılan çalışanın hesabının kapatılması","category":"Erişim/Hesap","body":"Ayrılan çalışanın hesabı son iş günü 18:00'de otomatik kapatılır.\n1) Yönetici, e-postalarının kime yönlendirileceğini 'Erişim/Hesap' ticketıyla bildirir.\n2) Kişisel dosyalar 30 gün saklanır; bu sürede yöneticinin talebiyle devredilebilir.\n3) Laptop ve ekipmanlar son gün IT ofisine teslim edilir."},{"title":"Yıllık izin talebi nasıl yapılır","category":"Diğer","body":"İzin talepleri İK portalından yapılır.\n1) ik.anka.local adresine şirket hesabınızla giriş yapın.\n2) 'İzin Talebi' > 'Yeni' > izin türü ve tarihleri seçin.\n3) Talep yöneticinize onaya gider; onaylanınca e-posta alırsınız.\nKalan izin gününüzü aynı ekranın üst kısmında görebilirsiniz."},{"title":"Bordro (maaş pusulası) görüntüleme","category":"Diğer","body":"Aylık bordronuz her ayın 15'inde İK portalında yayınlanır.\n1) ik.anka.local > 'Bordrolarım'a gidin.\n2) İlgili ayı seçip PDF olarak indirin.\nBordroda hata olduğunu düşünüyorsanız ik@anka.com.tr adresine yazın; bu konu IT değil İK birimindedir."},{"title":"Kartlı giriş ve otopark kartı","category":"Diğer","body":"Bina giriş kartınız çalışmıyorsa veya kaybettiyseniz:\n1) Resepsiyona gidin, kimliğinizle geçici kart alın.\n2) Kayıp kart güvenlik nedeniyle hemen iptal edilir; yeni kart 1 iş günü içinde hazırlanır.\n3) Otopark kartı talepleri idari işler birimine (idari@anka.com.tr) yapılır."}],"tickets":[{"title":"VPN'e bağlanamıyorum","description":"Anka Connect 'sunucuya ulaşılamıyor' diyor.","category":"Ağ/VPN","priority":"Low","reporter":"mehmet@anka.com","assignee":"ali@anka.com","status":"resolved","hoursAgo":1609.75,"resolvedAfterHours":1.12,"resolution":"Sunucu adresi eski kalmıştı, vpn.anka.com.tr olarak düzeltildi."},{"title":"VPN'e bağlanamıyorum - Kat 3","description":"Anka Connect 'sunucuya ulaşılamıyor' diyor.","category":"Ağ/VPN","priority":"Medium","reporter":"ece@anka.com","assignee":"ali@anka.com","status":"closed","hoursAgo":1428.96,"resolvedAfterHours":6.85,"resolution":"Sunucu adresi eski kalmıştı, vpn.anka.com.tr olarak düzeltildi."},{"title":"VPN'e bağlanamıyorum (acil)","description":"Anka Connect 'sunucuya ulaşılamıyor' diyor.","category":"Ağ/VPN","priority":"Low","reporter":"onur@anka.com","assignee":"mehmet@anka.com","status":"resolved","hoursAgo":652.2,"resolvedAfterHours":56.78,"resolution":"Sunucu adresi eski kalmıştı, vpn.anka.com.tr olarak düzeltildi."},{"title":"VPN bağlantısı kurulmuyor, yardım","description":"Şifremi giriyorum ama bağlanmıyor.","category":"Ağ/VPN","priority":"Low","reporter":"gizem@anka.com","assignee":"ali@anka.com","status":"closed","hoursAgo":162.72,"resolvedAfterHours":1